{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Cadazolid, a high-transfer analogue, showed very low oral bioavailability in healthy subjects, consistent with F < 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Ergotamine absolute oral bioavailability was less than 1% in patients, directly supporting a low-F outcome.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Tetrabenazine oral systemic availability was 0.049 ± 0.032, far below the 20% threshold, supporting low bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "MK-458 absolute oral bioavailability was 4.8% (range 3.5–5.8%) in patients, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Lumateperone absolute oral bioavailability was approximately 4.4% in humans, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "UK-224,671 oral bioavailability in humans was only 5–10%, supporting low F due to poor absorption and efflux.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Danazol fasted-state absolute bioavailability was 13%, supporting low F under non-fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Danazol fed-state absolute bioavailability reached 65%, a high-F outlier that is condition-specific and not applicable to rifampin co-treatment.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of high-transfer experimental evidence indicates low oral bioavailability. The query shares phenolic and basic-amine features with low-F analogues, and rifampin co-treatment would be expected to further induce first-pass metabolism/efflux, supporting F < 20%. The single fed-state high-F danazol record is condition-specific and does not outweigh the consistent low-F evidence.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule under rifampin co-treatment.",
    "No query-specific rifampin interaction record; transfer relies on structurally related low-F analogues.",
    "Fed-state high-F danazol data are not applicable to the rifampin condition."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

